<script>
(function(){
 var csrf=@json(csrf_token()), deleteActions=@json($reports->getCollection()->reject->trashed()->mapWithKeys(fn($report)=>[(string)$report->id=>route('assistant.fashion-advertising-reviews.destroy',$report)])), submittedTimes=@json($reports->getCollection()->mapWithKeys(fn($report)=>[(string)$report->id=>$report->created_at?->timezone('Asia/Shanghai')->format('Y-m-d H:i:s')]));
 var headerRow=document.querySelector('.review-table thead tr');if(headerRow&&headerRow.cells.length>=6){var submittedHeader=document.createElement('th');submittedHeader.textContent='提交时间';headerRow.insertBefore(submittedHeader,headerRow.cells[5]);}
 document.querySelectorAll('.review-table tbody>tr:not(.review-detail)').forEach(function(row){
  var detail=row.nextElementSibling,id=detail&&detail.id?detail.id.replace('fashion-review-',''):'',actions=row.querySelector('.review-actions');
  if(row.cells.length>=6){var submittedCell=document.createElement('td');submittedCell.style.whiteSpace='nowrap';submittedCell.textContent=submittedTimes[id]||'—';row.insertBefore(submittedCell,row.cells[5]);}
  if(actions){actions.querySelectorAll('form').forEach(function(form){if(form.querySelector('input[name="decision"]'))form.style.display='none';});var reject=actions.querySelector('.js-reject');if(reject)reject.style.display='none';}
  if(!actions||!deleteActions[id])return;
  var form=document.createElement('form');form.method='post';form.action=deleteActions[id];form.style.display='inline';form.innerHTML='<input type="hidden" name="_token" value="'+csrf+'"><input type="hidden" name="_method" value="DELETE"><button class="btn btn-default btn-xs" type="submit"><i class="fa fa-trash text-red"></i> 删除</button>';
  form.addEventListener('submit',function(e){if(!confirm('确认删除这份广告费提报吗？删除后运营可以重新填写，原记录仍会保留在已删除记录中。'))e.preventDefault();});actions.appendChild(form);
 });
 document.querySelectorAll('.review-status').forEach(function(item){if(item.textContent.trim()==='已删除')item.classList.add('deleted');});
 document.querySelectorAll('.review-actions [data-target^="#fashion-review-"]').forEach(function(button){var target=button.getAttribute('data-target');button.removeAttribute('data-toggle');button.removeAttribute('data-target');button.classList.add('js-review-detail');button.setAttribute('data-detail-target',target);});
 document.addEventListener('click',function(e){var button=e.target.closest&&e.target.closest('.js-review-detail');if(!button)return;var detail=document.querySelector(button.getAttribute('data-detail-target')),body=document.getElementById('fashion-review-detail-body');if(!detail||!body)return;var panels=detail.querySelectorAll('.review-panel'),advertising=panels.length>1?panels[1]:null,actions=detail.querySelector('.review-detail-actions');body.innerHTML='';if(advertising)body.appendChild(advertising.cloneNode(true));if(actions)body.appendChild(actions.cloneNode(true));jQuery('#fashion-review-detail-modal').modal('show');e.preventDefault();});
 document.addEventListener('click',function(e){var button=e.target.closest&&e.target.closest('.js-reject');if(!button)return;document.getElementById('fashion-reject-form').action=button.getAttribute('data-action');var detailModal=jQuery('#fashion-review-detail-modal'),rejectModal=jQuery('#fashion-reject-modal');if(detailModal.hasClass('in'))detailModal.one('hidden.bs.modal',function(){rejectModal.modal('show')}).modal('hide');else rejectModal.modal('show');});
})();
